use vstd::prelude::*;

verus! {
    fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> (index: Option<usize>)
        requires
            arr.len() <= 0x1_0000_0000, // Ensure the length of the array is within bounds
        ensures
            match index {
                Some(i) => 
                    i < arr.len() && arr[i] == target && 
                    (i == 0 || arr[i - 1] != target), // Ensure it's the first occurrence
                None => 
                    forall(|j: usize| j < arr.len() ==> arr[j] != target), // Ensure target is not found
            },
    {
        let mut left: usize = 0;
        let mut right: usize = arr.len();
        
        while left < right
            invariant
                left <= right,
                right <= arr.len(),
                forall(|j: usize| j < left ==> arr[j] != target), // All elements before left are not target
                forall(|j: usize| j < right ==> arr[j] <= target), // All elements in range are <= target
            decreases right - left,
        {
            let mid: usize = left + (right - left) / 2;
            if arr[mid] < target {
                left = mid + 1;
            } else {
                right = mid; // We might have found the target, continue searching left
            }
        }
        
        if left < arr.len() && arr[left] == target {
            Some(left) // Found the first occurrence
        } else {
            None // Target not found
        }
    }
}
